import { mkdirSync } from "node:fs";
import { dirname } from "node:path";
import { homedir } from "node:os";
import { DatabaseSync } from "node:sqlite";

const DEFAULT_DB_PATH = `${homedir()}/.openclaw/state/approval-delivery-dedupe.sqlite`;

// This is deliberately an at-most-once claim.  A Telegram request can be
// delivered by more than one handler invocation, including after a Gateway
// restart, but a given approval/channel/chat triple must never create another
// card.  A transport failure therefore remains visible in the durable audit
// record instead of being retried as an uncontrolled duplicate.
export class ApprovalDeliveryDedupe {
  constructor(dbPath = DEFAULT_DB_PATH) {
    this.dbPath = dbPath;
    this.db = null;
  }

  open() {
    if (this.db) return;
    mkdirSync(dirname(this.dbPath), { recursive: true });
    this.db = new DatabaseSync(this.dbPath);
    this.db.exec(`
      CREATE TABLE IF NOT EXISTS approval_delivery_dedupe (
        approval_id TEXT NOT NULL,
        channel TEXT NOT NULL,
        chat_id TEXT NOT NULL,
        status TEXT NOT NULL DEFAULT 'CLAIMED',
        created_at INTEGER NOT NULL,
        sent_at INTEGER,
        PRIMARY KEY (approval_id, channel, chat_id)
      );
    `);
  }

  claim({ approvalId, channel, chatId, now = Date.now() }) {
    if (!approvalId || !channel || chatId === undefined || chatId === null) return false;
    this.open();
    const result = this.db.prepare(`
      INSERT INTO approval_delivery_dedupe (approval_id, channel, chat_id, created_at)
      VALUES (?, ?, ?, ?)
      ON CONFLICT(approval_id, channel, chat_id) DO NOTHING
    `).run(String(approvalId), String(channel), String(chatId), now);
    return result.changes === 1;
  }

  markSent({ approvalId, channel, chatId, now = Date.now() }) {
    this.open();
    this.db.prepare(`
      UPDATE approval_delivery_dedupe SET status = 'SENT', sent_at = ?
      WHERE approval_id = ? AND channel = ? AND chat_id = ?
    `).run(now, String(approvalId), String(channel), String(chatId));
  }

  close() {
    this.db?.close();
    this.db = null;
  }
}

const defaultStore = new ApprovalDeliveryDedupe();

export function claimTelegramApprovalDelivery({ approvalId, chatId }) {
  return defaultStore.claim({ approvalId, channel: "telegram", chatId });
}

export function markTelegramApprovalDeliverySent({ approvalId, chatId }) {
  defaultStore.markSent({ approvalId, channel: "telegram", chatId });
}
